"use client";

import { useEffect, useId, useRef, useState, type ReactNode } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(" ");

export interface SelectProps {
  options: string[];
  /** The accessible name of the control, e.g. "Department". */
  label: string;
  /** Index of the selected option. Controlled when given with `onChange`. */
  value?: number;
  defaultValue?: number;
  onChange?: (index: number) => void;
  /** A glyph before the selected label, e.g. a calendar for a date range. */
  icon?: ReactNode;
  /** `sm` is the toolbar height, for a card head; `md` is the form height. */
  size?: "sm" | "md";
  /** Which edge of the trigger the list hangs from when it is narrower than the list. */
  align?: "start" | "end";
  className?: string;
}

const SIZE = {
  sm: "h-8 gap-2 px-3 text-xs",
  md: "h-10 gap-2 px-3.5 text-sm",
};

/**
 * A listbox behind a combobox trigger, with the house sliding highlight
 * between options. Ids come from `useId` so several selects can share a page,
 * and the highlight's `layoutId` is scoped the same way so two open lists do
 * not trade one highlight between them.
 */
export function Select({
  options,
  label,
  value,
  defaultValue = 0,
  onChange,
  icon,
  size = "md",
  align = "start",
  className = "",
}: SelectProps) {
  const uid = useId();
  const [open, setOpen] = useState(false);
  const [inner, setInner] = useState(defaultValue);
  const selected = value ?? inner;
  const [highlighted, setHighlighted] = useState(selected);
  const rootRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = useReducedMotion();

  const choose = (i: number) => {
    if (value === undefined) setInner(i);
    onChange?.(i);
    setOpen(false);
  };

  useEffect(() => {
    if (!open) return;
    const onClick = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, [open]);

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      if (!open) return setOpen(true);
      setHighlighted((h) => Math.min(h + 1, options.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setHighlighted((h) => Math.max(h - 1, 0));
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (open) choose(highlighted);
      else setOpen(true);
    } else if (e.key === "Escape") {
      setOpen(false);
    }
  };

  return (
    <div ref={rootRef} className={cx("relative", size === "md" ? "w-full max-w-xs" : "inline-block", className)}>
      <button
        type="button"
        role="combobox"
        aria-label={label}
        aria-expanded={open}
        aria-haspopup="listbox"
        aria-controls={`${uid}-listbox`}
        onClick={() => {
          setOpen((v) => !v);
          setHighlighted(selected);
        }}
        onKeyDown={handleKeyDown}
        className={cx(
          "flex w-full items-center justify-between rounded-md border border-stone-300 bg-stone-100 text-stone-900 outline-none transition-[border-color,box-shadow] duration-150 focus-visible:border-emerald-600 focus-visible:ring-2 focus-visible:ring-emerald-600/25 dark:border-stone-700 dark:bg-stone-950 dark:text-stone-100 dark:focus-visible:border-emerald-400 dark:focus-visible:ring-emerald-400/25",
          SIZE[size],
        )}
      >
        <span className="flex min-w-0 items-center gap-2">
          {icon && (
            <span aria-hidden className="shrink-0 text-stone-500 dark:text-stone-400">
              {icon}
            </span>
          )}
          <span className="truncate">{options[selected]}</span>
        </span>
        <motion.svg
          animate={{ rotate: open ? 180 : 0 }}
          transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 30 }}
          viewBox="0 0 24 24"
          width="16"
          height="16"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden
          className="shrink-0 text-stone-500"
        >
          <path d="m6 9 6 6 6-6" />
        </motion.svg>
      </button>

      <AnimatePresence>
        {open && (
          <motion.div
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0 }}
            style={{ transformOrigin: "top" }}
            transition={
              shouldReduceMotion
                ? { duration: 0 }
                : { duration: 0.18, ease: [0.22, 1, 0.36, 1] }
            }
            className={cx(
              "z-20 mt-1.5 min-w-full overflow-hidden rounded-lg border border-stone-200 bg-white shadow-[0_1px_2px_-1px_rgba(0,0,0,0.06),0_4px_12px_-4px_rgba(0,0,0,0.08)] dark:border-stone-700 dark:bg-stone-800 dark:shadow-none",
              // A form select takes its own width and pushes what is under it
              // down; a toolbar select floats over the content beneath.
              size === "sm" && "absolute w-max",
              size === "sm" && (align === "end" ? "right-0" : "left-0"),
            )}
          >
            <ul
              id={`${uid}-listbox`}
              role="listbox"
              aria-label={label}
              aria-activedescendant={`${uid}-option-${highlighted}`}
              data-lenis-prevent
              className="scrollbar-thin max-h-48 overflow-y-auto overscroll-contain p-1"
            >
              {options.map((option, i) => (
                <motion.li
                  key={option}
                  id={`${uid}-option-${i}`}
                  role="option"
                  aria-selected={selected === i}
                  initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0, x: -4 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: shouldReduceMotion ? 0 : i * 0.03, duration: 0.15 }}
                  onMouseEnter={() => setHighlighted(i)}
                  onClick={() => choose(i)}
                  className={cx("relative cursor-pointer rounded-md px-3 py-2", size === "sm" ? "text-xs" : "text-sm")}
                >
                  {highlighted === i && (
                    <motion.span
                      layoutId={`${uid}-highlight`}
                      className="absolute inset-0 rounded-md bg-stone-100 dark:bg-stone-700"
                      transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 600, damping: 40 }}
                    />
                  )}
                  <span
                    className={cx(
                      "relative flex items-center justify-between gap-4",
                      highlighted === i ? "text-stone-900 dark:text-stone-100" : "text-stone-700 dark:text-stone-300",
                    )}
                  >
                    {option}
                    {selected === i && <span aria-hidden className="text-emerald-700 dark:text-emerald-400">✓</span>}
                  </span>
                </motion.li>
              ))}
            </ul>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
